using System.Text.RegularExpressions;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Text;

namespace Morris.Roslynk.Infrastructure.Razor;

/// <summary>
/// Finds and removes unnecessary <c>@using</c> directives in a <c>.razor</c>/<c>.cshtml</c> file. The compiler
/// never reports CS8019 in generated code, so the Razor-generated document is re-parsed as ordinary code
/// (its <c>&lt;auto-generated&gt;</c> marker blanked, offsets unchanged) and compiled in place of the original;
/// each CS8019 using is mapped through its <c>#line</c> directive to the <c>@using</c> line that produced it.
/// Only directives written in the file itself are removed: usings mapped from an imports file such as
/// <c>_Imports.razor</c> or <c>_ViewImports.cshtml</c> are shared by other components and left alone.
/// </summary>
public static partial class RazorUnusedUsings
{
	private const string UnnecessaryUsingId = "CS8019";

	[GeneratedRegex(@"<auto-generated\s*/?>", RegexOptions.IgnoreCase)]
	private static partial Regex AutoGeneratedMarker();

	/// <summary>True for imports files, whose directives apply to every component or view beneath them.</summary>
	public static bool IsImportsFile(string path)
	{
		string name = Path.GetFileName(path);
		return string.Equals(name, "_Imports.razor", StringComparison.OrdinalIgnoreCase)
			|| string.Equals(name, "_ViewImports.cshtml", StringComparison.OrdinalIgnoreCase);
	}

	/// <summary>
	/// Returns <paramref name="updated"/> with the unnecessary <c>@using</c> lines of <paramref name="source"/>
	/// removed (only the one on the 0-based <paramref name="line"/> when given), and how many were removed.
	/// </summary>
	public static async Task<(Solution Updated, int Removed)> RemoveAsync(
		Solution updated,
		RazorSourceDocument source,
		int? line,
		CancellationToken cancellationToken = default)
	{
		if (source.RazorPath is not string razorPath || source.RazorText is not SourceText razorText || IsImportsFile(razorPath))
			return (updated, 0);

		IReadOnlyList<TextSpan> lines = await FindUnusedLinesAsync(source, razorPath, razorText, cancellationToken);
		if (line is int target)
			lines = lines.Where(span => razorText.Lines.GetLineFromPosition(span.Start).LineNumber == target).ToArray();
		if (lines.Count == 0)
			return (updated, 0);

		SourceText rewritten = razorText.WithChanges(lines.Select(line => new TextChange(line, "")));
		foreach (DocumentId documentId in updated.GetDocumentIdsWithFilePath(razorPath))
		{
			if (updated.GetAdditionalDocument(documentId) is not null)
				updated = updated.WithAdditionalDocumentText(documentId, rewritten);
		}

		return (updated, lines.Count);
	}

	/// <summary>
	/// The full lines (including their line break) of the file's unnecessary @using directives, in order. A file
	/// can have several generated documents (declarations split off from the render tree), each repeating the
	/// file's usings, so a line is unnecessary only when every document that carries it reports it unused.
	/// </summary>
	private static async Task<IReadOnlyList<TextSpan>> FindUnusedLinesAsync(RazorSourceDocument source, string razorPath, SourceText razorText, CancellationToken cancellationToken)
	{
		var unused = new SortedDictionary<int, TextSpan>();
		var used = new HashSet<int>();
		foreach (Document generated in source.Documents)
		{
			(IReadOnlyDictionary<int, TextSpan> Unused, IReadOnlySet<int> Used)? probed =
				await ProbeAsync(generated, source, razorText, cancellationToken);
			if (probed is not var (documentUnused, documentUsed))
				return [];

			foreach ((int start, TextSpan line) in documentUnused)
				unused[start] = line;
			used.UnionWith(documentUsed);
		}

		return unused.Where(pair => !used.Contains(pair.Key)).Select(pair => pair.Value).ToArray();
	}

	/// <summary>
	/// Compiles <paramref name="generated"/> as ordinary code and classifies each file-local @using line it carries:
	/// unused (reported CS8019) or used. Null when the document cannot be analysed.
	/// </summary>
	private static async Task<(IReadOnlyDictionary<int, TextSpan> Unused, IReadOnlySet<int> Used)?> ProbeAsync(
		Document generated,
		RazorSourceDocument source,
		SourceText razorText,
		CancellationToken cancellationToken)
	{
		SyntaxTree? tree = await generated.GetSyntaxTreeAsync(cancellationToken);
		Compilation? compilation = await generated.Project.GetCompilationAsync(cancellationToken);
		if (tree is null || compilation is null)
			return null;

		string generatedText = (await tree.GetTextAsync(cancellationToken)).ToString();
		string probeText = AutoGeneratedMarker().Replace(generatedText, match => new string(' ', match.Length));
		SyntaxTree probe = CSharpSyntaxTree.ParseText(
			probeText,
			(CSharpParseOptions)tree.Options,
			path: tree.FilePath + ".probe.cs",
			cancellationToken: cancellationToken);

		Compilation probed = compilation.ReplaceSyntaxTree(tree, probe);
		SyntaxNode probeRoot = await probe.GetRootAsync(cancellationToken);

		var unusedNames = new HashSet<TextSpan>();
		foreach (Diagnostic diagnostic in probed.GetSemanticModel(probe).GetDiagnostics(cancellationToken: cancellationToken))
		{
			if (diagnostic.Id != UnnecessaryUsingId)
				continue;

			UsingDirectiveSyntax? directive = probeRoot.FindNode(diagnostic.Location.SourceSpan).FirstAncestorOrSelf<UsingDirectiveSyntax>();
			if (directive?.NamespaceOrType is NameSyntax name)
				unusedNames.Add(name.Span);
		}

		var unused = new Dictionary<int, TextSpan>();
		var used = new HashSet<int>();
		foreach (UsingDirectiveSyntax directive in probeRoot.DescendantNodes().OfType<UsingDirectiveSyntax>())
		{
			if (directive.NamespaceOrType is not NameSyntax name)
				continue;

			FileLinePositionSpan mapped = probe.GetMappedLineSpan(name.Span, cancellationToken);
			if (!mapped.HasMappedPath || !source.MapsToSource(mapped.Path))
				continue;
			if (mapped.StartLinePosition.Line >= razorText.Lines.Count)
				continue;

			TextLine line = razorText.Lines[mapped.StartLinePosition.Line];
			string lineText = line.ToString().Trim();
			if (!lineText.StartsWith("@using", StringComparison.Ordinal) || !lineText.Contains(name.ToString(), StringComparison.Ordinal))
				continue;

			if (unusedNames.Contains(name.Span))
				unused[line.Start] = line.SpanIncludingLineBreak;
			else
				used.Add(line.Start);
		}

		return (unused, used);
	}
}
